const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.clock.install();await p.addInitScript(require('./island-test-helper.cjs'));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.evaluate(()=>{window.speak=()=>Promise.resolve();window.tone=()=>{}});await p.click('#learningTab');
await p.evaluate(()=>{const j=DEUTSCH_JOURNEY;j.select(0);sessionStorage.setItem('marketOriginal',JSON.stringify(profileStorage.getItem(j.key)));if(document.querySelector('[data-market-visit]'))throw Error('Merchant leaked into first island');j.select(1);if(document.querySelector('[data-market-visit]').dataset.marketVisit!=='ready')throw Error('New learner market state');});await p.click('#marketVisit');
for(const width of [320,390,1280]){await p.setViewportSize({width,height:1000});await p.evaluate(()=>DEUTSCH_JOURNEY.open(1));await p.locator('#learningView img').evaluateAll(xs=>xs.forEach(i=>i.loading='eager'));await p.waitForFunction(()=>[...document.querySelectorAll('#learningView img')].every(i=>i.complete&&i.naturalWidth>0));if(await p.locator('[data-market-state="welcome"]').count()!==1||await p.locator('.al-study-grid img').count()!==6)throw Error('Market greeting/material changed');if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Market intro overflow '+width);fs.mkdirSync('audit-screenshots',{recursive:true});await p.screenshot({path:'audit-screenshots/market-intro-'+width+'.png',fullPage:true});}
await p.setViewportSize({width:390,height:1000});await p.click('#alContinue');await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE,j=DEUTSCH_JOURNEY;if(!document.querySelector('.market-task-context'))throw Error('Missing practice story');if(a.snapshot().queue.length!==30||a.snapshot().queue.filter(t=>t.assessment).length!==0)throw Error('Market queue changed');finishTrainingToTest();while(!a.snapshot().finished){const s=a.snapshot(),q=s.queue[s.index];a.answer(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}if(document.querySelector('[data-market-state]').dataset.marketState!=='success'||j.load().lessons[1].best!==100)throw Error('Missing merchant success/seal');});await p.waitForFunction(()=>[...document.querySelectorAll('#learningView img')].every(i=>i.complete&&i.naturalWidth>0));await p.screenshot({path:'audit-screenshots/market-success.png',fullPage:true});
await p.click('#alDone');if(await p.locator('[data-market-visit="complete"]').count()!==1)throw Error('Map did not remember completed encounter');await p.reload();await p.evaluate(()=>{window.speak=()=>Promise.resolve();window.tone=()=>{}});await p.click('#learningTab');if(await p.locator('[data-market-visit="complete"]').count()!==1)throw Error('Encounter lost on reload');await p.click('#marketVisit');await p.click('#alContinue');await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE,j=DEUTSCH_JOURNEY;finishTrainingToTest();while(!a.snapshot().finished)a.skip();if(document.querySelector('[data-market-state]').dataset.marketState!=='encourage')throw Error('Failed retry must show encouragement');if(!j.load().lessons[1].passed||j.load().lessons[1].best!==100||j.load().lessons[1].last!==0)throw Error('Failed retry erased seal/best');if(profileStorage.getItem('deutsch16_journey_v1')!==JSON.parse(sessionStorage.getItem('marketOriginal')))throw Error('Market modified first island');});await p.waitForFunction(()=>[...document.querySelectorAll('#learningView img')].every(i=>i.complete&&i.naturalWidth>0));await p.screenshot({path:'audit-screenshots/market-encourage.png',fullPage:true});
await p.evaluate(()=>{const j=DEUTSCH_JOURNEY;document.documentElement.lang='en';j.open(1);if(!document.querySelector('[data-market-state]').textContent.includes('Welcome to the market!'))throw Error('Missing English merchant');j.open(0);if(document.querySelector('[data-market-state]'))throw Error('Merchant leaked into another lesson');j.select(0);j.open(1);if(document.querySelector('[data-market-state]'))throw Error('Merchant leaked into first-island lesson');});if(errors.length)throw Error(errors.join(';'));console.log('PASS Benno market mission, three loaded reaction portraits, unchanged six-card/separate-training-test lesson, context without answer hints, success/retry, permanent seal, reload and first-island isolation, English and 320–1280px');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
